package process

import (
	"context"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"testing"
	"time"
)

func TestTimeoutKillsDescendantsHoldingOutput(t *testing.T) {
	pidFile := filepath.Join(t.TempDir(), "child.pid")
	result := make(chan error, 1)
	go func() {
		_, err := (Runner{}).Run(context.Background(), 100*time.Millisecond, "/bin/sh", "-c", `sleep 10 & echo $! > "$1"; wait`, "sh", pidFile)
		result <- err
	}()
	defer func() {
		b, _ := os.ReadFile(pidFile)
		pid, _ := strconv.Atoi(strings.TrimSpace(string(b)))
		if pid > 1 {
			_ = syscall.Kill(pid, syscall.SIGKILL)
		}
	}()
	select {
	case err := <-result:
		if err == nil {
			t.Fatal("stalled command succeeded")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("timeout left an inherited output pipe open")
	}
}

func TestCommandOutputIsBounded(t *testing.T) {
	out, err := (Runner{}).Run(context.Background(), time.Second, "head", "-c", "2097152", "/dev/zero")
	if err == nil || len(out) > 1<<20 {
		t.Fatalf("unbounded output: bytes=%d err=%v", len(out), err)
	}
}

package proxy

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

type benchmarkTransport struct{}

func (benchmarkTransport) RoundTrip(*http.Request) (*http.Response, error) {
	return &http.Response{StatusCode: 200, Header: make(http.Header), Body: io.NopCloser(strings.NewReader("ok"))}, nil
}

func BenchmarkProxy(b *testing.B) {
	p := New()
	p.transport = benchmarkTransport{}
	backend, err := NewBackend("http://127.0.0.1:8080")
	if err != nil {
		b.Fatal(err)
	}
	p.Set(backend)
	r := httptest.NewRequest("GET", "/", nil)
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		p.ServeHTTP(httptest.NewRecorder(), r)
	}
}

func TestDrainAfterEarlierRequestCompleted(t *testing.T) {
	b, err := NewBackend("http://127.0.0.1:1")
	if err != nil {
		t.Fatal(err)
	}
	b.enter()
	b.leave()
	b.enter()
	if b.Drain(context.Background(), time.Millisecond) {
		t.Fatal("drain ignored a request after an earlier request completed")
	}
	b.leave()
	if !b.Drain(context.Background(), time.Second) {
		t.Fatal("completed backend did not drain")
	}
}

func TestUnavailableAndAtomicPerRequestCutover(t *testing.T) {
	p := New()
	r := httptest.NewRequest("GET", "/", nil)
	w := httptest.NewRecorder()
	p.ServeHTTP(w, r)
	if w.Code != 503 {
		t.Fatal(w.Code)
	}
	a := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "a") }))
	defer a.Close()
	b := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "b") }))
	defer b.Close()
	ba, _ := NewBackend(a.URL)
	bb, _ := NewBackend(b.URL)
	p.Set(ba)
	w = httptest.NewRecorder()
	p.ServeHTTP(w, r)
	if w.Body.String() != "a" {
		t.Fatal()
	}
	if old := p.Set(bb); old != ba {
		t.Fatal()
	}
	w = httptest.NewRecorder()
	p.ServeHTTP(w, r)
	if w.Body.String() != "b" {
		t.Fatal()
	}
}

package image

import (
	"context"
	"flag"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"testing"
	"time"

	"github.com/example/easy-service/internal/process"
)

var realOCI = flag.Bool("real-oci", false, "test actual OCI pull and unpack as an unprivileged user")

func TestRealRootlessOCI(t *testing.T) {
	if !*realOCI {
		t.Skip("enable with -args -real-oci")
	}
	if os.Geteuid() == 0 {
		t.Fatal("run this test as an unprivileged user")
	}
	for _, command := range []string{"skopeo", "umoci"} {
		if _, err := exec.LookPath(command); err != nil {
			t.Fatal(err)
		}
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
	// A real multi-platform index: the copied architecture manifest has a
	// different digest, and rootless unpack must preserve a usable filesystem.
	ref := "alpine@sha256:d9e853e87e55526f6b2917df91a2115c36dd7c696a35be12163d44e6e2a4b6bc"
	m := Manager{Data: t.TempDir(), Runner: process.Runner{}}
	p, err := m.Prepare(ctx, ref)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := os.ReadFile(filepath.Join(p.Rootfs, "etc", "alpine-release")); err != nil {
		t.Fatal(err)
	}
	if err := m.Prune(p); err != nil {
		t.Fatal(err)
	}
	cached, err := m.Cached(ref, p.Digest)
	if err != nil || !reflect.DeepEqual(cached, p) {
		t.Fatalf("cache mismatch: %+v %v", cached, err)
	}
}

package supervisor

import (
	"context"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/example/easy-service/internal/config"
	"github.com/example/easy-service/internal/health"
	"github.com/example/easy-service/internal/proxy"
	"github.com/example/easy-service/internal/revision"
	"github.com/example/easy-service/internal/sandbox"
	"github.com/example/easy-service/internal/state"
)

var soak = flag.Duration("soak", 0, "duration of real-Git/HTTP deployment and leak stress test")

type soakHealthTransport struct {
	http.RoundTripper
	proxy *proxy.Proxy
	t     *testing.T
}

func (s soakHealthTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	started := time.Now()
	res, err := s.RoundTripper.RoundTrip(req)
	if b := s.proxy.Current(); err != nil && b != nil && req.URL.Host == b.URL.Host && req.Context().Err() != context.Canceled {
		s.t.Logf("serving health probe failed after %s: %v", time.Since(started), err)
	}
	return res, err
}

func TestDeploymentSoak(t *testing.T) {
	if *soak <= 0 {
		t.Skip("enable with -args -soak=3m")
	}
	origin := t.TempDir()
	if b, err := exec.Command("git", "init", "-b", "main", origin).CombinedOutput(); err != nil {
		t.Fatalf("git init: %v: %s", err, b)
	}
	sha := commitVersion(t, origin, "good-initial")
	data := t.TempDir()
	// Leave scheduling headroom for concurrent traffic and the race detector.
	// Short deadline and stalled-probe behavior have separate focused tests.
	cfg := config.Config{DataDir: data, GitURL: origin, RuntimeImage: "test-image", RunCommand: "owned-http-boundary", StartupTimeout: time.Second, HealthInterval: 250 * time.Millisecond, HealthFailures: 3}
	rt := &httpRuntime{Runtime: sandbox.Runtime{Data: data}}
	git := revision.New(origin, "", data)
	ctx, cancel := context.WithCancel(context.Background())
	e := &Engine{Cfg: cfg, Runtime: rt, Checkout: git, Proxy: proxy.New(), Store: state.Store{Data: data}, Health: health.New(cfg.HealthInterval, "/health"), Rootfs: t.TempDir(), Digest: "sha256:test", Drain: 2 * time.Second, RuntimeContext: ctx, Failures: make(chan uint64, 1)}
	checker := e.Health.(*health.Checker)
	checker.Client.Transport = soakHealthTransport{checker.Client.Transport, e.Proxy, t}
	t.Cleanup(func() { e.Shutdown(context.Background()); cancel() })
	if _, err := git.Select(ctx, "commit", "main", "*"); err != nil {
		t.Fatal(err)
	}
	if err := e.Deploy(ctx, revision.Selection{SHA: sha}); err != nil {
		t.Fatal(err)
	}
	front := httptest.NewServer(e.Proxy)
	defer front.Close()
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.Proxy = nil
	transport.MaxIdleConnsPerHost = 16
	transport.MaxConnsPerHost = 16
	defer transport.CloseIdleConnections()
	client := &http.Client{Transport: transport, Timeout: 2 * time.Second}
	trafficCtx, stopTraffic := context.WithCancel(ctx)
	var workers sync.WaitGroup
	var requests, outages, epoch atomic.Uint64
	failures := make(chan string, 1)
	for n := 0; n < 8; n++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for trafficCtx.Err() == nil {
				before := epoch.Load()
				req, _ := http.NewRequestWithContext(trafficCtx, "GET", front.URL, nil)
				res, err := client.Do(req)
				body := ""
				status := 0
				if err == nil {
					b, readErr := io.ReadAll(res.Body)
					_ = res.Body.Close()
					body, status, err = string(b), res.StatusCode, readErr
				}
				if trafficCtx.Err() != nil {
					return
				}
				if err == nil && status == 200 && strings.HasPrefix(body, "good-") {
					requests.Add(1)
					continue
				}
				if before%2 == 1 || before != epoch.Load() {
					outages.Add(1)
					continue
				}
				select {
				case failures <- fmt.Sprintf("unexpected serving failure: status=%d body=%q err=%v", status, body, err):
				default:
				}
				return
			}
		}()
	}
	defer func() { stopTraffic(); workers.Wait() }()
	started := time.Now()
	end := started.Add(*soak)
	var baseline runtime.MemStats
	baseGoroutines := 0
	cycles := 0
	for time.Now().Before(end) {
		cycles++
		version := fmt.Sprintf("good-%d", cycles)
		if cycles%10 == 0 {
			version = "bad"
		}
		if cycles%10 == 5 {
			version = "stall"
		}
		commitVersion(t, origin, version)
		sel, err := git.Select(ctx, "commit", "main", "*")
		if err != nil {
			t.Fatal(err)
		}
		err = e.Deploy(ctx, sel)
		if strings.HasPrefix(version, "good-") != (err == nil) {
			t.Fatalf("candidate %q: %v", version, err)
		}
		if cycles%8 == 0 {
			e.mu.Lock()
			generation := e.active.generation
			e.mu.Unlock()
			if err := e.Replace(ctx, generation); err != nil {
				t.Fatal(err)
			}
		}
		if cycles%12 == 0 {
			for failure := 0; failure < 2; failure++ {
				epoch.Add(1)
				e.mu.Lock()
				active := e.active
				e.mu.Unlock()
				_ = active.Instance.Stop(ctx)
				if err := e.Recover(ctx, active.generation); err != nil {
					t.Fatal(err)
				}
				epoch.Add(1)
			}
		}
		select {
		case err := <-failures:
			t.Fatal(err)
		default:
		}
		for _, name := range []string{"instances", "prepared", "deployments"} {
			entries, err := os.ReadDir(filepath.Join(data, name))
			// A rejected candidate may retain one prepared cache for retry.
			limit := 1
			if name == "prepared" {
				limit = 3
			}
			if name == "deployments" {
				limit = 0
			}
			if err != nil || len(entries) > limit {
				t.Fatalf("%s grows without cleanup: %d %v", name, len(entries), err)
			}
		}
		if cycles%20 == 0 {
			runtime.GC()
			var current runtime.MemStats
			runtime.ReadMemStats(&current)
			goroutines := runtime.NumGoroutine()
			if baseGoroutines == 0 {
				baseline = current
				baseGoroutines = goroutines
			}
			if current.HeapAlloc > baseline.HeapAlloc+16<<20 || goroutines > baseGoroutines+64 {
				t.Fatalf("resources grow across deployments: heap=%d baseline=%d goroutines=%d baseline=%d", current.HeapAlloc, baseline.HeapAlloc, goroutines, baseGoroutines)
			}
			t.Logf("elapsed=%s cycles=%d successful_requests=%d expected_outage_requests=%d heap_bytes=%d goroutines=%d", time.Since(started).Round(time.Second), cycles, requests.Load(), outages.Load(), current.HeapAlloc, goroutines)
		}
	}
	stopTraffic()
	workers.Wait()
	select {
	case err := <-failures:
		t.Fatal(err)
	default:
	}
	t.Logf("completed duration=%s cycles=%d successful_requests=%d expected_outage_requests=%d", time.Since(started), cycles, requests.Load(), outages.Load())
	if cycles < 20 || requests.Load() < 1000 {
		t.Fatal("soak did not exercise enough deployments and traffic")
	}
}

package image

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"
)

type fake struct{ calls []string }

var sourceDigest = "sha256:" + strings.Repeat("a", 64)
var copiedDigest = "sha256:" + strings.Repeat("b", 64)

func (f *fake) Run(_ context.Context, _ time.Duration, n string, a ...string) (string, error) {
	f.calls = append(f.calls, n+" "+strings.Join(a, " "))
	if n == "skopeo" && a[0] == "inspect" {
		if strings.HasPrefix(a[len(a)-1], "oci:") {
			return copiedDigest + "\n", nil
		}
		return sourceDigest + "\n", nil
	}
	if n == "skopeo" && a[0] == "copy" {
		layout := strings.TrimSuffix(strings.TrimPrefix(a[len(a)-1], "oci:"), ":runtime")
		if err := os.MkdirAll(filepath.Join(layout, "blobs"), 0700); err != nil {
			return "", err
		}
		for i, arg := range a {
			if arg == "--digestfile" {
				return "", os.WriteFile(a[i+1], []byte(copiedDigest), 0600)
			}
		}
		return "", fmt.Errorf("copy must record its result digest")
	}
	if n == "umoci" {
		if !strings.Contains(strings.Join(a, " "), "--rootless") {
			return "", fmt.Errorf("rootless unpack required")
		}
		for _, x := range a {
			if strings.HasSuffix(x, "/bundle") {
				if err := os.MkdirAll(filepath.Join(x, "rootfs"), 0700); err != nil {
					return "", err
				}
				return "", os.WriteFile(filepath.Join(x, "config.json"), []byte(`{"process":{"env":["PATH=/usr/local/go/bin:/usr/bin:/bin","IMAGE_DEFAULT=present"]}}`), 0600)
			}
		}
	}
	return "", nil
}
func TestDigestArchitectureCacheAndPreparation(t *testing.T) {
	f := &fake{}
	m := Manager{t.TempDir(), f}
	p, e := m.Prepare(context.Background(), "example/app:latest")
	if e != nil {
		t.Fatal(e)
	}
	if p.Digest != sourceDigest || len(f.calls) != 4 || !reflect.DeepEqual(p.Env, []string{"PATH=/usr/local/go/bin:/usr/bin:/bin", "IMAGE_DEFAULT=present"}) {
		t.Fatalf("%+v %v", p, f.calls)
	}
	if _, e = m.Prepare(context.Background(), "example/app:latest"); e != nil {
		t.Fatal(e)
	}
	if len(f.calls) != 5 {
		t.Fatalf("cache missed: %v", f.calls)
	}
	if !strings.Contains(f.calls[0], "--override-arch") {
		t.Fatal("architecture not selected")
	}
	if !strings.Contains(f.calls[1], "docker://example/app@"+sourceDigest) {
		t.Fatalf("copy did not use immutable digest: %v", f.calls)
	}
}

func TestPruneKeepsSelectedImageAndOfflineEnvironment(t *testing.T) {
	m := Manager{Data: t.TempDir(), Runner: &fake{}}
	old, err := m.Prepare(context.Background(), "example/app:old")
	if err != nil {
		t.Fatal(err)
	}
	current, err := m.Prepare(context.Background(), "example/app:new")
	if err != nil {
		t.Fatal(err)
	}
	if err := m.Prune(Prepared{Rootfs: t.TempDir()}); err == nil {
		t.Fatal("unsafe cleanup path accepted")
	}
	if err := m.Prune(current); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(old.Rootfs); !os.IsNotExist(err) {
		t.Fatal("stale image cache retained:", err)
	}
	for _, name := range []string{"oci", "copied-digest"} {
		if _, err := os.Stat(filepath.Join(filepath.Dir(filepath.Dir(current.Rootfs)), name)); !os.IsNotExist(err) {
			t.Fatal("unused image source retained:", name, err)
		}
	}
	cached, err := m.Cached("example/app:new", sourceDigest)
	if err != nil || !reflect.DeepEqual(cached, current) {
		t.Fatalf("offline environment lost after pruning: %+v %v", cached, err)
	}
	// A failed new image must leave the selected cache available for recovery.
	m.Runner = runnerFunc(func(context.Context, time.Duration, string, ...string) (string, error) {
		return "", errors.New("registry unavailable")
	})
	if _, err := m.Prepare(context.Background(), "example/app:new"); err == nil {
		t.Fatal("registry failure ignored")
	}
	if recovered, err := m.Cached("example/app:new", sourceDigest); err != nil || !reflect.DeepEqual(recovered, current) {
		t.Fatalf("offline image recovery failed: %+v %v", recovered, err)
	}
}

func TestPinnedDigestMismatchFailsBeforePull(t *testing.T) {
	f := &fake{}
	m := Manager{t.TempDir(), f}
	if _, e := m.Prepare(context.Background(), "example/app@sha256:different"); e == nil {
		t.Fatal("accepted mismatched pinned digest")
	}
	if len(f.calls) != 1 {
		t.Fatalf("image was pulled after mismatch: %v", f.calls)
	}
}

type runnerFunc func(context.Context, time.Duration, string, ...string) (string, error)

func (f runnerFunc) Run(ctx context.Context, limit time.Duration, n string, a ...string) (string, error) {
	return f(ctx, limit, n, a...)
}

func TestCopiedDigestMismatchAndUnpackFailureRemovePartialCache(t *testing.T) {
	for _, phase := range []string{"digest", "unpack", "config"} {
		t.Run(phase, func(t *testing.T) {
			base := &fake{}
			m := Manager{Data: t.TempDir(), Runner: runnerFunc(func(ctx context.Context, limit time.Duration, n string, a ...string) (string, error) {
				if phase == "digest" && n == "skopeo" && a[0] == "inspect" && strings.HasPrefix(a[len(a)-1], "oci:") {
					return "sha256:" + strings.Repeat("c", 64), nil
				}
				if phase == "unpack" && n == "umoci" {
					return "", errors.New("unpack failed")
				}
				out, err := base.Run(ctx, limit, n, a...)
				if phase == "config" && n == "umoci" && err == nil {
					err = os.WriteFile(filepath.Join(a[len(a)-1], "config.json"), []byte("invalid-json"), 0600)
				}
				return out, err
			})}
			if _, err := m.Prepare(context.Background(), "registry.invalid:5000/app:tag"); err == nil {
				t.Fatal("broken cache accepted")
			}
			entries, err := os.ReadDir(filepath.Join(m.Data, "images"))
			if err != nil || len(entries) != 0 {
				t.Fatalf("partial cache retained: %d %v", len(entries), err)
			}
			if !strings.Contains(base.calls[1], "docker://registry.invalid:5000/app@"+sourceDigest) {
				t.Fatal("digest pin damaged registry port or retained image tag")
			}
		})
	}
}

func TestCachedRootfsMustBelongToItsImage(t *testing.T) {
	m := Manager{Data: t.TempDir(), Runner: &fake{}}
	p, err := m.Prepare(context.Background(), "example/app:tag")
	if err != nil {
		t.Fatal(err)
	}
	meta := filepath.Join(filepath.Dir(filepath.Dir(p.Rootfs)), "ready.json")
	p.Rootfs = t.TempDir()
	b, err := json.Marshal(p)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(meta, b, 0600); err != nil {
		t.Fatal(err)
	}
	if _, err := m.Cached("example/app:tag", p.Digest); err == nil {
		t.Fatal("unrelated rootfs accepted from cache metadata")
	}
}

package state

import (
	"context"
	"encoding/json"
	"github.com/example/easy-service/internal/process"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"reflect"
	"syscall"
	"testing"
	"time"
)

func TestAtomicStateRecoveryAndCleanup(t *testing.T) {
	d := t.TempDir()
	s := Store{Data: d}
	v := State{Revision: "abc", GitURL: "/source/one", ImageRef: "image"}
	if e := s.Save(v); e != nil {
		t.Fatal(e)
	}
	got, e := s.Load()
	if e != nil || !reflect.DeepEqual(got, v) {
		t.Fatalf("%+v %v", got, e)
	}
	if !got.Recoverable(v.GitURL, v.ImageRef) || got.Recoverable("/source/two", v.ImageRef) || got.Recoverable(v.GitURL, "changed-image") {
		t.Fatal("saved recovery revision was not restricted to its source and image")
	}
	legacy := got
	legacy.GitURL = ""
	if legacy.Recoverable(v.GitURL, v.ImageRef) {
		t.Fatal("legacy state without source identity was accepted for recovery")
	}
	for _, name := range []string{"instances", "runtime", "deployments"} {
		os.MkdirAll(filepath.Join(d, name, "orphan"), 0700)
	}
	if e = s.Reconcile(); e != nil {
		t.Fatal(e)
	}
	for _, name := range []string{"instances", "runtime", "deployments"} {
		if _, e = os.Stat(filepath.Join(d, name)); !os.IsNotExist(e) {
			t.Fatalf("orphan %s retained", name)
		}
	}
	if _, e = s.Load(); !os.IsNotExist(e) {
		t.Fatal("stale state retained")
	}
}

func TestReconcileHelperProcess(t *testing.T) {
	if os.Getenv("EASY_SERVICE_RECONCILE_HELPER") != "1" {
		return
	}
	if os.Getenv("EASY_SERVICE_IGNORE_TERM") == "1" {
		signal.Ignore(syscall.SIGTERM)
	}
	if err := os.WriteFile(os.Getenv("EASY_SERVICE_READY"), []byte("ready"), 0600); err != nil {
		os.Exit(2)
	}
	for {
		time.Sleep(time.Hour)
	}
}

func reconcileProcess(t *testing.T, data, name, area string, ignoreTerm bool) (*exec.Cmd, <-chan struct{}) {
	t.Helper()
	bundle := filepath.Join(data, area, "orphan")
	if err := os.MkdirAll(bundle, 0700); err != nil {
		t.Fatal(err)
	}
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	helper := filepath.Join(t.TempDir(), name)
	if err := os.Link(exe, helper); err != nil {
		t.Fatal(err)
	}
	ready := filepath.Join(bundle, "running")
	cmd := exec.Command(helper, "-test.run=TestReconcileHelperProcess", "--", "--rootless=true", "--network=host", "--file-access=exclusive", "--root", filepath.Join(data, "runtime", "orphan"), "run", "--bundle", bundle, "orphan")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Env = []string{"EASY_SERVICE_RECONCILE_HELPER=1", "EASY_SERVICE_READY=" + ready}
	if ignoreTerm {
		cmd.Env = append(cmd.Env, "EASY_SERVICE_IGNORE_TERM=1")
	}
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	done := make(chan struct{})
	go func() { _ = cmd.Wait(); close(done) }()
	t.Cleanup(func() { _ = syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL); <-done })
	deadline := time.Now().Add(time.Second)
	for {
		if _, err := os.Stat(ready); err == nil {
			break
		}
		if time.Now().After(deadline) {
			t.Fatal("helper did not start")
		}
		time.Sleep(time.Millisecond)
	}
	return cmd, done
}

func TestReconcileStopsOnlyOwnedUIDs(t *testing.T) {
	if os.Geteuid() != 0 {
		t.Skip("UID isolation requires root")
	}
	data, other := t.TempDir(), t.TempDir()
	var owners []RuntimeOwner
	var commands []*exec.Cmd
	for _, dir := range []string{data, other} {
		owner, err := NewRuntimeOwner(dir, "orphan")
		if err != nil {
			t.Fatal(err)
		}
		owners = append(owners, owner)
		cmd := exec.Command("/bin/sh", "-c", "trap '' TERM; sleep 600 & wait")
		cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true, Credential: &syscall.Credential{Uid: owner.UID, Gid: owner.UID}}
		if err := cmd.Start(); err != nil {
			t.Fatal(err)
		}
		commands = append(commands, cmd)
		t.Cleanup(func() {
			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			_ = process.KillUser(ctx, owner.UID)
			_ = cmd.Wait()
			_ = owner.Release()
		})
		deadline := time.Now().Add(time.Second)
		for {
			s, err := process.SampleUser(owner.UID)
			if err == nil && len(s.PIDs) >= 2 {
				break
			}
			if time.Now().After(deadline) {
				t.Fatal("helper did not fork")
			}
			time.Sleep(time.Millisecond)
		}
	}
	if err := (Store{Data: data}).Reconcile(); err != nil {
		t.Fatal(err)
	}
	s, err := process.SampleUser(owners[0].UID)
	if err != nil || len(s.PIDs) != 0 {
		t.Fatal("owned orphan survived", s, err)
	}
	s, err = process.SampleUser(owners[1].UID)
	if err != nil || len(s.PIDs) == 0 {
		t.Fatal("unrelated supervisor was stopped", s, err)
	}
	_ = commands
}

func TestReconcileDoesNotSignalUnrelatedPID(t *testing.T) {
	for _, name := range []string{"runsc", "unrelated-runsc"} {
