	if err := old.Kill(context.Background()); err != nil {
		t.Fatal(err)
	}
	response, err = http.Get(candidate.Endpoint())
	if err != nil {
		t.Fatal("peer instance stopped", err)
	}
	body, _ = io.ReadAll(response.Body)
	response.Body.Close()
	if string(body) != "candidate" {
		t.Fatal("wrong peer response")
	}
}
