func TestServiceMemoryLimitSemantics(t *testing.T) {
	validEnvironment(t)
	c, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if c.ServiceMemoryLimit != 512<<20 {
		t.Fatalf("default memory limit=%d", c.ServiceMemoryLimit)
	}
	for _, value := range []string{"", "0"} {
		t.Run("disabled-"+value, func(t *testing.T) {
			validEnvironment(t)
			t.Setenv("SERVICE_MEMORY_LIMIT", value)
			c, err := Load()
			if err != nil || c.ServiceMemoryLimit != 0 {
				t.Fatalf("limit=%d err=%v", c.ServiceMemoryLimit, err)
			}
		})
	}
	t.Setenv("SERVICE_MEMORY_LIMIT", "2G")
	c, err = Load()
	if err != nil || c.ServiceMemoryLimit != 2<<30 {
		t.Fatalf("limit=%d err=%v", c.ServiceMemoryLimit, err)
	}
	t.Setenv("SERVICE_MEMORY_LIMIT", "-1")
	if _, err = Load(); err == nil {
		t.Fatal("negative memory limit accepted")
	}
}
func TestInvalid(t *testing.T) {
	for _, tc := range []struct{ k, v string }{{"GIT_URL", "http://github.com/a/b"}, {"GIT_URL", "https://x:y@github.com/a/b"}} {
		validEnvironment(t)
		t.Setenv("RUNTIME_IMAGE", "x")
		t.Setenv("RUN_COMMAND", "x")
		t.Setenv(tc.k, tc.v)
		if _, e := Load(); e == nil {
			t.Fatalf("accepted %s", tc.v)
		}
	}
}

func TestLocalRepositoryConfiguration(t *testing.T) {
	validEnvironment(t)
	path := t.TempDir()
	t.Setenv("GIT_URL", path)
	c, err := Load()
	if err != nil || c.GitURL != path {
		t.Fatalf("local path rejected: url=%q err=%v", c.GitURL, err)
	}
	t.Setenv("UPDATE_METHOD", "release")
	if _, err := Load(); err == nil {
		t.Fatal("local repository accepted GitHub release mode")
	}
	t.Setenv("UPDATE_METHOD", "commit")
	t.Setenv("GIT_URL", filepath.Join(path, "missing"))
	if _, err := Load(); err == nil {
		t.Fatal("missing local repository accepted")
	}
}

func TestDurationMustFitPositiveNanoseconds(t *testing.T) {
	validEnvironment(t)
	for _, value := range []string{"0.0000000001", "9223372036.854776", "NaN", "Inf", "-1"} {
		t.Setenv("POLL_INTERVAL", value)
		if _, err := Load(); err == nil {
			t.Fatalf("accepted duration that cannot drive a ticker: %q", value)
		}
	}
}

package health

import (
	"context"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"
	"time"
)

type proc struct {
	exited atomic.Bool
	done   chan error
}

func newProc() *proc               { return &proc{done: make(chan error)} }
func (p *proc) Exited() bool       { return p.exited.Load() }
func (p *proc) Done() <-chan error { return p.done }
func (p *proc) exit()              { p.exited.Store(true); close(p.done) }
func TestTimeoutCalculation(t *testing.T) {
	if ProbeTimeout(10*time.Second) != 3*time.Second || ProbeTimeout(2*time.Second) != time.Second {
		t.Fatal()
	}
}
func TestRedirectFailsAndSuccessResetsFailures(t *testing.T) {
	var n atomic.Int64
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		x := n.Add(1)
		if x == 2 {
			w.WriteHeader(200)
		} else {
			w.WriteHeader(500)
		}
	}))
	defer s.Close()
	c := New(20*time.Millisecond, "/")
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	if got := c.UntilFailure(ctx, s.URL, newProc(), 2); got != ThresholdFailed || n.Load() != 4 {
		t.Fatalf("result=%v probes=%d", got, n.Load())
	}
}
func TestExitImmediate(t *testing.T) {
	p := newProc()
	p.exit()
	c := New(time.Hour, "/")
	if c.Ready(context.Background(), "http://127.0.0.1:1", p, time.Hour) == nil {
		t.Fatal()
	}
}

func TestExitInterruptsLivenessWait(t *testing.T) {
	p := newProc()
	c := New(time.Hour, "/")
	result := make(chan Result, 1)
	go func() { result <- c.UntilFailure(context.Background(), "http://127.0.0.1:1", p, 3) }()
	time.Sleep(10 * time.Millisecond)
	p.exit()
	select {
	case got := <-result:
		if got != ProcessExited {
			t.Fatalf("result=%v", got)
		}
	case <-time.After(200 * time.Millisecond):
		t.Fatal("process exit did not interrupt health wait")
	}
}
